sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    // =====================================================
    // UPDATE OPPORTUNITY STATUS
    // =====================================================

    c.updateOpportunityStatus = function(opportunity) {

        if (!opportunity || !opportunity.sys_id) {

            return;

        }


        opportunity.updating = true;


        // Send update request to Server Script

        c.data.action =
            'update_status';

        c.data.opportunity_sys_id =
            opportunity.sys_id;

        c.data.new_status =
            opportunity.edit_status;


        c.server.update().then(
            function(response) {

                opportunity.updating = false;


                // Server successfully updated

                if (
                    response.data.update_success
                ) {

                    /*
                     * Server Script has already
                     * reloaded the opportunity list.
                     *
                     * Therefore:
                     * - table status updates
                     * - Open count updates
                     * - Closed count updates
                     * - statistics update
                     */

                }

            },
            function() {

                opportunity.updating = false;

            }
        );

    };

};

sp_widget.css:
/* =========================================
   PAGE
========================================= */

.opportunities-page {

  max-width: 1200px;

  margin: 30px auto;

  padding:
    0 20px 50px;

  color: #102a56;

}


/* =========================================
   HEADER
========================================= */

.page-header {

  background: #ffffff;

  border:
    1px solid #e1e7f2;

  border-radius: 18px;

  padding: 30px 34px;

  margin-bottom: 24px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;

  box-shadow:
    0 8px 25px
    rgba(30,55,90,0.08);

}


.eyebrow {

  font-size: 12px;

  font-weight: 700;

  letter-spacing: 2px;

  color: #4d63e8;

}


.page-header h1 {

  margin:
    8px 0 6px;

  font-size: 30px;

  font-weight: 700;

}


.page-header p {

  margin: 0;

  color: #70809d;

  font-size: 14px;

}


.company-info {

  display: inline-block;

  margin-top: 12px;

  padding:
    7px 12px;

  background: #f2f4ff;

  border-radius: 7px;

  color: #5368e8;

  font-size: 12px;

  font-weight: 600;

}


.header-actions {

  display: flex;

  gap: 10px;

}


/* =========================================
   BUTTONS
========================================= */

.btn {

  height: 42px;

  padding:
    0 18px;

  border-radius: 8px;

  font-size: 13px;

  font-weight: 600;

  cursor: pointer;

  transition: 0.2s;

}


.btn-primary {

  background: #5368e8;

  color: #ffffff;

  border:
    1px solid #5368e8;

}


.btn-primary:hover {

  background: #4056d5;

}


.btn-secondary {

  background: #ffffff;

  color: #5368e8;

  border:
    1px solid #ccd5e5;

}


.btn-secondary:hover {

  background: #f5f7ff;

}


/* =========================================
   STATS
========================================= */

.stats-grid {

  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 18px;

  margin-bottom: 24px;

}


.stat-card {

  background: #ffffff;

  border:
    1px solid #e1e7f2;

  border-radius: 15px;

  padding: 20px;

  display: flex;

  align-items: center;

  gap: 15px;

  box-shadow:
    0 5px 18px
    rgba(30,55,90,0.05);

}


.stat-icon {

  width: 45px;

  height: 45px;

  border-radius: 11px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #f1f3ff;

  color: #5368e8;

  font-size: 20px;

}


.stat-icon.open {

  background: #effaf3;

  color: #25804a;

}


.stat-icon.closed {

  background: #fff2f2;

  color: #c64b4b;

}


.stat-label {

  color: #7a89a2;

  font-size: 12px;

  margin-bottom: 5px;

}


.stat-value {

  font-size: 24px;

  font-weight: 700;

  color: #20385f;

}


/* =========================================
   LIST CARD
========================================= */

.list-card {

  background: #ffffff;

  border:
    1px solid #e1e7f2;

  border-radius: 18px;

  overflow: hidden;

  box-shadow:
    0 8px 25px
    rgba(30,55,90,0.06);

}


.list-header {

  padding:
    24px 28px;

  display: flex;

  justify-content: space-between;

  align-items: center;

  border-bottom:
    1px solid #e8edf5;

}


.list-header h2 {

  margin: 0 0 5px;

  font-size: 20px;

}


.list-header p {

  margin: 0;

  color: #7888a3;

  font-size: 13px;

}


.record-count {

  padding:
    7px 12px;

  background: #f2f4ff;

  color: #5368e8;

  border-radius: 7px;

  font-size: 12px;

  font-weight: 600;

}


/* =========================================
   TABLE
========================================= */

.table-wrapper {

  width: 100%;

  overflow-x: auto;

}


.opportunity-table {

  width: 100%;

  border-collapse: collapse;

}


.opportunity-table th {

  padding:
    14px 18px;

  text-align: left;

  background: #f8faff;

  border-bottom:
    1px solid #e4eaf3;

  color: #71809a;

  font-size: 11px;

  font-weight: 700;

  text-transform: uppercase;

  letter-spacing: 0.4px;

  white-space: nowrap;

}


.opportunity-table td {

  padding:
    17px 18px;

  border-bottom:
    1px solid #edf1f6;

  font-size: 13px;

  color: #405575;

  white-space: nowrap;

}


.opportunity-table tbody tr:hover {

  background: #fafbff;

}


/* =========================================
   OPPORTUNITY
========================================= */

.opportunity-main {

  display: flex;

  flex-direction: column;

  gap: 4px;

}


.opportunity-main strong {

  color: #20385f;

  font-size: 13px;

}


.opportunity-main span {

  color: #8a97aa;

  font-size: 11px;

}


.type-text {

  color: #5368e8;

  font-weight: 600;

}


/* =========================================
   APPLICATION COUNT
========================================= */

.application-count {

  display: inline-flex;

  min-width: 30px;

  height: 26px;

  padding: 0 8px;

  align-items: center;

  justify-content: center;

  border-radius: 6px;

  background: #f2f4ff;

  color: #5368e8;

  font-weight: 700;

}


/* =========================================
   STATUS
========================================= */

.status-badge {

  display: inline-block;

  padding:
    5px 10px;

  border-radius: 20px;

  font-size: 11px;

  font-weight: 700;

}


.status-open {

  background: #eaf8ef;

  color: #25804a;

}


.status-closed {

  background: #f1f3f6;

  color: #68758a;

}


/* =========================================
   EMPTY
========================================= */

.empty-state {

  text-align: center;

  padding:
    70px 30px;

}


.empty-icon {

  width: 55px;

  height: 55px;

  margin:
    0 auto 15px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #f2f4ff;

  border-radius: 14px;

  color: #5368e8;

  font-size: 24px;

}


.empty-state h3 {

  margin:
    0 0 8px;

  font-size: 18px;

  color: #20385f;

}


.empty-state p {

  max-width: 450px;

  margin:
    0 auto 20px;

  color: #7c8ba2;

  font-size: 13px;

  line-height: 1.6;

}


/* =========================================
   ERROR
========================================= */

.error-message {

  margin-bottom: 20px;

  padding:
    13px 16px;

  border-radius: 8px;

  background: #fff1f1;

  border:
    1px solid #ffd1d1;

  color: #c63f3f;

  font-size: 13px;

}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 768px) {

  .page-header {

    flex-direction: column;

    align-items: flex-start;

  }


  .header-actions {

    width: 100%;

  }


  .header-actions .btn {

    flex: 1;

  }


  .stats-grid {

    grid-template-columns: 1fr;

  }


  .list-header {

    flex-direction: column;

    align-items: flex-start;

    gap: 12px;

  }

}


.btn {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  text-decoration: none;

  height: 42px;

  padding: 0 18px;

  border-radius: 8px;

  font-size: 13px;

  font-weight: 600;

  cursor: pointer;

  transition: 0.2s;

  box-sizing: border-box;

}





/* =========================================
   STATUS EDITOR
========================================= */

.status-editor {

  display: flex;

  align-items: center;

  gap: 8px;

}


/* STATUS SELECT */

.status-select {

  height: 32px;

  min-width: 90px;

  padding: 0 9px;

  border:
    1px solid #d8deeb;

  border-radius: 7px;

  background: #ffffff;

  color: #405575;

  font-size: 12px;

  font-weight: 600;

  cursor: pointer;

  outline: none;

}


.status-select:focus {

  border-color: #5368e8;

  box-shadow:
    0 0 0 2px
    rgba(83,104,232,0.10);

}


/* UPDATE BUTTON */

.status-update-btn {

  height: 32px;

  padding:
    0 11px;

  border:
    1px solid #5368e8;

  border-radius: 7px;

  background: #5368e8;

  color: #ffffff;

  font-size: 11px;

  font-weight: 700;

  cursor: pointer;

  transition: 0.2s;

}


.status-update-btn:hover {

  background: #4056d5;

}


.status-update-btn:disabled {

  opacity: 0.55;

  cursor: not-allowed;

}

sp_widget.script:
(function() {

    /*
     * =====================================================
     * CAMPUS360 RECRUITER - OPPORTUNITIES
     * =====================================================
     *
     * Current recruiter:
     * Ananya Mehta
     * Recruiter ID: RCR001
     *
     * Current company:
     * TechNova Solutions
     * Company ID: CMP001
     *
     * IMPORTANT:
     * This page currently works ONLY for this company.
     * Later this can be replaced with logged-in recruiter
     * / company mapping.
     */


	    // =====================================================
    // UPDATE OPPORTUNITY STATUS
    // =====================================================

    if (
        input &&
        input.action == 'update_status'
    ) {

        var updateGR =
            new GlideRecord(
                'x_snc_campus360_placement_opportunity'
            );


        if (
            updateGR.get(
                input.opportunity_sys_id
            )
        ) {

            // Make sure this opportunity
            // belongs to our sample company

            if (
                updateGR.getValue('company') ==
                'e9268662acd303107f44b432e349694b'
            ) {

                updateGR.setValue(
                    'status',
                    input.new_status
                );

                updateGR.update();

                data.update_success = true;

            } else {

                data.update_success = false;

                data.error =
                    'You are not authorized to update this opportunity.';

            }

        } else {

            data.update_success = false;

            data.error =
                'Opportunity record could not be found.';

        }

    }


    // =====================================================
    // COMPANY CONTEXT
    // =====================================================

    var companySysId =
        'e9268662acd303107f44b432e349694b';


    data.recruiter_name =
        'Ananya Mehta';

    data.recruiter_id =
        'RCR001';


    // =====================================================
    // GET COMPANY
    // =====================================================

    var companyGR =
        new GlideRecord(
            'x_snc_campus360_company_master'
        );


    if (!companyGR.get(companySysId)) {

        data.error =
            'Company record could not be found.';

        return;

    }


    data.company_name =
        companyGR.getValue('company_name');

    data.company_id =
        companyGR.getValue('company_id');


    // =====================================================
    // OPPORTUNITY STATISTICS
    // =====================================================

    data.total_count = 0;

    data.open_count = 0;

    data.closed_count = 0;


    var statsGR =
        new GlideRecord(
            'x_snc_campus360_placement_opportunity'
        );


    /*
     * VERY IMPORTANT:
     *
     * Only opportunities belonging to this company.
     */

    statsGR.addQuery(
        'company',
        companySysId
    );

    statsGR.query();


    while (statsGR.next()) {

        data.total_count++;


        var status =
            statsGR.getValue('status');


        if (
            status &&
            status.toLowerCase() == 'open'
        ) {

            data.open_count++;

        } else {

            data.closed_count++;

        }

    }


    // =====================================================
    // OPPORTUNITY LIST
    // =====================================================

    data.opportunities = [];


    var opportunityGR =
        new GlideRecord(
            'x_snc_campus360_placement_opportunity'
        );


    /*
     * COMPANY FILTER
     *
     * This is the most important filter on this page.
     */

    opportunityGR.addQuery(
        'company',
        companySysId
    );


    /*
     * Newest opportunities first.
     */

    opportunityGR.orderByDesc(
        'sys_created_on'
    );


    opportunityGR.query();


    while (
        opportunityGR.next()
    ) {

        var opportunity = {};


        // -------------------------------------------------
        // SYS ID
        // -------------------------------------------------

        opportunity.sys_id =
            opportunityGR.getUniqueValue();


        // -------------------------------------------------
        // OPPORTUNITY ID
        // -------------------------------------------------

        opportunity.opportunity_id =
            opportunityGR.getValue(
                'opportunity_id'
            );


        // -------------------------------------------------
        // TITLE
        // -------------------------------------------------

        opportunity.title =
            opportunityGR.getValue(
                'opportunity_title'
            );


        // -------------------------------------------------
        // TYPE
        // -------------------------------------------------

        opportunity.type =
            opportunityGR.getDisplayValue(
                'opportunity_type'
            );


        // -------------------------------------------------
        // LOCATION
        // -------------------------------------------------

        opportunity.location =
            opportunityGR.getValue(
                'location'
            );


        // -------------------------------------------------
        // CTC / STIPEND
        // -------------------------------------------------

        opportunity.ctc =
            opportunityGR.getValue(
                'ctc_stipend'
            );


        // -------------------------------------------------
        // DEADLINE
        // -------------------------------------------------

        var deadline =
            opportunityGR.getValue(
                'application_deadline'
            );


        if (deadline) {

            var deadlineGDT =
                new GlideDateTime(
                    deadline
                );


            opportunity.deadline =
                deadlineGDT
                    .getDate()
                    .getByFormat(
                        'dd MMM yyyy'
                    );

        } else {

            opportunity.deadline =
                'Not specified';

        }


        // =================================================
		// STATUS
		// =================================================

		opportunity.status =
			opportunityGR.getDisplayValue('status');

		// Keep the actual choice value
		// for the dropdown

		opportunity.edit_status =
			opportunityGR.getValue('status');


        // -------------------------------------------------
        // CREATED DATE
        // -------------------------------------------------

        opportunity.created =
            opportunityGR.getDisplayValue(
                'sys_created_on'
            );


        // -------------------------------------------------
        // APPLICATION COUNT
        // -------------------------------------------------

        opportunity.application_count = 0;


        var applicationGR =
            new GlideAggregate(
                'x_snc_campus360_student_application'
            );


        /*
         * Application
         * ->
         * Opportunity
         */

        applicationGR.addQuery(
            'opportunity',
            opportunityGR.getUniqueValue()
        );


        applicationGR.addAggregate(
            'COUNT'
        );


        applicationGR.query();


        if (
            applicationGR.next()
        ) {

            opportunity.application_count =
                parseInt(
                    applicationGR.getAggregate(
                        'COUNT'
                    ),
                    10
                );

        }


        data.opportunities.push(
            opportunity
        );

    }


})();
